/* ============================================================================
 * codec_main.c — 端到端语音编解码 (wav-in -> wav-out)
 *
 * 真实传输边界: 发送方只传 idx (量化索引), 接收方用 idx 反量化特征再送 decoder.
 *   send: audio -> encoder -> en_encoder -> quantizer -> idx文件  (只产出/传输 idx)
 *   recv: idx文件 -> quantizer_to_features(反量化) -> en_decoder -> decoder -> audio
 *   loop: 进程内 audio -> ... -> idx -> ... -> audio (等价于 send+recv, 供对照/旧脚本)
 *
 * 与 Python `infer_light.py` 的 LightInferWrapper 行为对齐:
 *   - preprocess: 右填充到 fill_length=hop_length=96 的倍数 (codec.py:79)
 *   - decode 截断: 取重建前 length 个样本 (infer_light.py:114 recon[:, :length])
 *
 * 注意: 输入 wav 需已 resample 到 16k (与 librosa.load(sr=16000) 一致).
 *
 * Build (见 test/build.sh 中 codec_main 段):
 *   gcc -I../header -O2 -o codec_main.exe codec_main.c \
 *       ../src/nn_ops.c ../src/blocks.c ../src/transformer.c \
 *       ../src/encoder.c ../src/decoder.c ../src/quantizer.c ../src/fsq_codec.c -lm
 *
 * Run:
 *   codec_main.exe <in.wav> <out.wav>              # loop (进程内, 兼容旧调用)
 *   codec_main.exe send <in.wav> <out.idx>          # 发送方: 音频 -> idx
 *   codec_main.exe recv <in.idx> <out.wav>          # 接收方: idx -> 音频
 * ========================================================================== */
#include "nn_infer.h"
#include "fsq_codec.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

/* right-pad to multiple of HOP_LENGTH * EN_ENC_COMPRESS_RATE.
 * Python codec.py pads to fill_length = hop_length * en_coder_compress_rate,
 * i.e. the full audio->latent downsampling factor. C must match exactly so the
 * latent token count equals Python's ceil(L/factor) rather than floor(L/factor). */
static float* preprocess(const float *a, int len, int *out_len) {
    int frame = HOP_LENGTH * EN_ENC_COMPRESS_RATE;
    int pad = (frame - (len % frame)) % frame;
    int n = len + pad;
    float *buf = (float*)malloc(sizeof(float) * n);
    for (int i = 0; i < len; i++) buf[i] = a[i];
    for (int i = len; i < n; i++) buf[i] = 0.0f;
    *out_len = n;
    return buf;
}

/* read 16-bit PCM WAV; downmix to mono; returns float32 in [-1,1] */
static int read_wav(const char *path, float **out, int *orig_len) {
    FILE *f = fopen(path, "rb");
    if (!f) { fprintf(stderr, "[err] cannot open %s\n", path); return -1; }
    unsigned char h[12];
    if (fread(h, 1, 12, f) != 12 || memcmp(h, "RIFF", 4) != 0 ||
        memcmp(h + 8, "WAVE", 4) != 0) {
        fclose(f); fprintf(stderr, "[err] %s is not a WAVE file\n", path); return -1;
    }
    int sr = 0, ch = 0, bits = 0;
    unsigned char ck[8];
    while (fread(ck, 1, 8, f) == 8) {
        unsigned int sz = ck[4] | (ck[5] << 8) | (ck[6] << 16) | ((unsigned int)ck[7] << 24);
        if (memcmp(ck, "fmt ", 4) == 0) {
            unsigned char fmt[16];
            if (fread(fmt, 1, 16, f) != 16) { fclose(f); return -1; }
            ch  = fmt[2] | (fmt[3] << 8);
            sr  = fmt[4] | (fmt[5] << 8) | (fmt[6] << 16) | ((unsigned int)fmt[7] << 24);
            bits = fmt[14] | (fmt[15] << 8);
            int rem = (int)sz - 16; if (rem > 0) fseek(f, rem, SEEK_CUR);
        } else if (memcmp(ck, "data", 4) == 0) {
            if (bits != 16) {
                fclose(f); fprintf(stderr, "[err] %s bits=%d (need 16-bit PCM)\n", path, bits); return -1;
            }
            unsigned int frames = sz / (2u * (unsigned)ch);
            float *buf = (float*)malloc(sizeof(float) * frames);
            for (unsigned int i = 0; i < frames; i++) {
                int s_sum = 0;
                for (int c = 0; c < ch; c++) {
                    short s;
                    if (fread(&s, 2, 1, f) != 1) { fclose(f); return -1; }
                    s_sum += s;
                }
                buf[i] = (s_sum / (float)ch) / 32768.0f;
            }
            fclose(f);
            if (sr != 16000)
                fprintf(stderr, "[warn] %s sr=%d (C expects 16000; resample before running)\n", path, sr);
            *out = buf; *orig_len = (int)frames;
            return 0;
        } else {
            fseek(f, (long)sz, SEEK_CUR);
        }
    }
    fclose(f); return -1;
}

/* write 16-bit PCM mono WAV at 16k */
static int write_wav(const char *path, const float *x, int n) {
    FILE *f = fopen(path, "wb");
    if (!f) { fprintf(stderr, "[err] cannot open %s for write\n", path); return -1; }
    int data_bytes = n * 2;
    int chunk = 36 + data_bytes;
    unsigned char rh[12];
    memcpy(rh, "RIFF", 4);
    rh[4] = chunk & 0xff; rh[5] = (chunk >> 8) & 0xff;
    rh[6] = (chunk >> 16) & 0xff; rh[7] = (chunk >> 24) & 0xff;
    memcpy(rh + 8, "WAVE", 4);
    fwrite(rh, 1, 12, f);
