/* loop 模式: 进程内 audio -> idx -> audio (等价于 send+recv, 供对照) */
static int run_loop(const char *in_wav, const char *out_wav) {
    float *audio; int origT;
    if (read_wav(in_wav, &audio, &origT) != 0) return 1;
    int Tt; int64_t *idx;
    encode_to_idx(audio, origT, &Tt, &idx);
    float *rec;
    decode_from_idx(idx, Tt, origT, &rec);
    write_wav(out_wav, rec, origT);
    fprintf(stderr, "[ok][loop] %s -> %s  orig=%d Tt=%d tokens\n", in_wav, out_wav, origT, Tt);
    free(audio); free(idx); free(rec);
    return 0;
}

/* send 模式: 音频 -> idx 文件 (只产出传输用的 idx) */
static int run_send(const char *in_wav, const char *idx_path) {
    float *audio; int origT;
    if (read_wav(in_wav, &audio, &origT) != 0) return 1;
    int Tt; int64_t *idx;
    int T0 = encode_to_idx(audio, origT, &Tt, &idx);
    int Tlat = Tt / EN_ENC_COMPRESS_RATE;          /* 实际量化 token 数(仅用于比特率统计) */
    write_idx(idx_path, 1, Tt, origT, idx);         /* 头记帧数 Tt, 数据写 B*Tlat 个 token */
    /* 真实比特率: 按索引空间算每 token 有效比特数 (FSQ levels 乘积的 log2) */
    int64_t maxidx = 0;
    for (int i = 0; i < Tlat; i++) if (idx[i] > maxidx) maxidx = idx[i];
    int bits = 0; int64_t m = maxidx;
    while (m > 0) { bits++; m >>= 1; }            /* ceil(log2(maxidx+1)) */
    double kbps = (double)Tlat * bits / ((double)T0 / 16000.0) / 1000.0;
    fprintf(stderr, "[ok][send] %s -> %s  orig=%d padded=%d Tlat=%d tokens  %d bits/token -> %.2f kbps @16k\n",
            in_wav, idx_path, origT, T0, Tlat, bits, kbps);
    free(audio); free(idx);
    return 0;
}

/* recv 模式: idx 文件 -> 音频 (接收方反量化 + decoder) */
static int run_recv(const char *idx_path, const char *out_wav) {
    int B, Tt, origT; int64_t *idx;
    if (read_idx(idx_path, &B, &Tt, &origT, &idx) != 0) return 1;
    float *rec;
    decode_from_idx(idx, Tt, origT, &rec);
    write_wav(out_wav, rec, origT);
    fprintf(stderr, "[ok][recv] %s -> %s  B=%d Tt=%d orig=%d\n", idx_path, out_wav, B, Tt, origT);
    free(idx); free(rec);
    return 0;
}

/* 信道误码注入(C 端到端独立 BER 测试用):
 * 对 idx 的 18-bit packed 表示的每个 bit, 以概率 ber 独立翻转, 然后 clip 到 (1<<18)-1.
 * 这与 infer_light.corrupt_bits 的逐 bit 语义一致; 配合 quantizer 的 Gray-clamp,
 * 每 bit 错误只影响一个量化 level, 符合"方向-1"抗误码设计. */
static uint32_t xs32(uint32_t *s) {
    uint32_t x = *s;
    x ^= x << 13; x ^= x >> 17; x ^= x << 5;
    *s = x; return x;
}
static int run_inject(const char *in_idx, const char *out_idx, double ber, uint32_t seed) {
    int B, Tt, origT; int64_t *idx;
    if (read_idx(in_idx, &B, &Tt, &origT, &idx) != 0) return 1;
    uint32_t s = seed ? seed : 0x9e3779b9u;
    const int64_t cap = (1LL << FSQ_TOTAL_BITS) - 1;   /* total_bits=18 */
    for (int i = 0; i < B * Tt; i++) {
        uint32_t v = (uint32_t)idx[i];
        for (int b = 0; b < FSQ_TOTAL_BITS; b++)
            if ((double)xs32(&s) / 4294967296.0 < ber) v ^= (1u << b);
        if ((int64_t)v > cap) v = (uint32_t)cap;
        idx[i] = (int64_t)v;
    }
    write_idx(out_idx, B, Tt, origT, idx);
    fprintf(stderr, "[ok][inject] %s -> %s  ber=%.2e tokens=%d (per-bit flip, clip %lld-bit)\n",
            in_idx, out_idx, ber, B * Tt, (long long)FSQ_TOTAL_BITS);
    free(idx);
    return 0;
}

int main(int argc, char **argv) {
    if (argc == 3) {
        /* 兼容旧调用: 进程内 loop */
        return run_loop(argv[1], argv[2]);
    }
    if (argc == 4 && strcmp(argv[1], "send") == 0) {
        return run_send(argv[2], argv[3]);
    }
    if (argc == 4 && strcmp(argv[1], "recv") == 0) {
        return run_recv(argv[2], argv[3]);
    }
    if (argc >= 5 && strcmp(argv[1], "inject") == 0) {
        double ber = atof(argv[4]);
        uint32_t seed = (argc >= 6) ? (uint32_t)strtoul(argv[5], NULL, 10) : 0u;
        return run_inject(argv[2], argv[3], ber, seed);
    }
    fprintf(stderr,
        "usage:\n"
        "  %s <in.wav> <out.wav>                       # loop (进程内 encode+decode, 兼容旧调用)\n"
        "  %s send <in.wav> <out.idx>                  # 发送方: 音频 -> idx (只传 idx)\n"
        "  %s recv <in.idx> <out.wav>                  # 接收方: idx -> 音频 (反量化 + decoder)\n"
        "  %s inject <in.idx> <out.idx> <ber> [seed]   # 信道误码注入 (per-bit 翻转)\n",
        argv[0], argv[0], argv[0], argv[0]);
    return 2;
}

