    T yout = t_alloc(3, (int[]){1, Co, T_in});
    conv1d_d(W, b, &tmp, &yout, Ci, Co, k, 1, pad, 1, T_in, dil);
    memcpy(y, yout.d, (size_t)Co * T_in * sizeof(float));
