#include <stdio.h>
#include <stdlib.h>
#include "fsq_codec.h"

/* Cross-check the C codec against Python ground-truth vectors.
 * Usage: test_fsq_codec <vectors_learnable.csv>
 * Expects header "idx,l0,l1,l2,l3,l4,l5" then N data rows.
 *
 * Three pass criteria (all must hold, fails==0):
 *   1. DECODE : C learnable_index_to_level_indices(idx) == Python levels
 *   2. ENCODE : C level_indices_to_learnable_index(levels) == Python idx
 *   3. ROUNDTRIP: decode(encode(levels)) == levels  (self-consistency)
 * Plus the C per-bit error-isolation statistic reproduces ~0.16 changed levels,
 * confirming the per-level resilience claim holds on the C side too. */
int main(int argc, char **argv) {
    const char *path = (argc > 1) ? argv[1] : "vectors_learnable.csv";
    FILE *f = fopen(path, "r");
    if (!f) { fprintf(stderr, "cannot open %s\n", path); return 2; }

    char line[256];
    if (!fgets(line, sizeof(line), f)) { fclose(f); return 2; } /* skip header */

    int count = 0, dec_fails = 0, enc_fails = 0, rt_fails = 0;
    long long total_changes = 0; int flips = 0;

    while (fgets(line, sizeof(line), f)) {
        unsigned long idx;
        int l[FSQ_DIM];
        if (sscanf(line, "%lu,%d,%d,%d,%d,%d,%d",
                   &idx, &l[0], &l[1], &l[2], &l[3], &l[4], &l[5]) != 7)
            continue;

        /* 1) DECODE: packed idx -> levels */
        int out[FSQ_DIM];
        learnable_index_to_level_indices((uint32_t)idx, out);
        int dec_ok = 1;
        for (int d = 0; d < FSQ_DIM; d++) if (out[d] != l[d]) dec_ok = 0;
        if (!dec_ok) {
            dec_fails++;
            if (dec_fails <= 5)
                printf("DECODE MISMATCH idx=%lu got[%d %d %d %d %d %d] exp[%d %d %d %d %d %d]\n",
                       idx, out[0], out[1], out[2], out[3], out[4], out[5],
                       l[0], l[1], l[2], l[3], l[4], l[5]);
        }

        /* 2) ENCODE: levels -> packed idx */
        uint32_t e = level_indices_to_learnable_index(l);
        if (e != (uint32_t)idx) {
            enc_fails++;
            if (enc_fails <= 5)
                printf("ENCODE MISMATCH levels[%d %d %d %d %d %d] got=%u exp=%lu\n",
                       l[0], l[1], l[2], l[3], l[4], l[5], e, idx);
        }

        /* 3) ROUNDTRIP: decode(encode(levels)) == levels */
        int rt[FSQ_DIM];
        learnable_index_to_level_indices(e, rt);
        int rt_ok = 1;
        for (int d = 0; d < FSQ_DIM; d++) if (rt[d] != l[d]) rt_ok = 0;
        if (!rt_ok) {
            rt_fails++;
            if (rt_fails <= 5)
                printf("ROUNDTRIP FAIL levels[%d %d %d %d %d %d] got[%d %d %d %d %d %d]\n",
                       l[0], l[1], l[2], l[3], l[4], l[5],
                       rt[0], rt[1], rt[2], rt[3], rt[4], rt[5]);
        }

        count++;

        /* per-bit isolation: flip each of 18 bits, count changed levels */
        for (int b = 0; b < FSQ_TOTAL_BITS; b++) {
            uint32_t fi = ((uint32_t)idx) ^ (1u << b);
            int fo[FSQ_DIM];
            learnable_index_to_level_indices(fi, fo);
            int ch = 0;
            for (int d = 0; d < FSQ_DIM; d++) if (fo[d] != l[d]) ch++;
            total_changes += ch; flips++;
        }
    }
    fclose(f);

    int all_fails = dec_fails + enc_fails + rt_fails;
    printf("=== C codec alignment test ===\n");
    printf("vectors            = %d\n", count);
    printf("decode fails       = %d\n", dec_fails);
    printf("encode fails       = %d\n", enc_fails);
    printf("roundtrip fails    = %d\n", rt_fails);
    printf("TOTAL fails        = %d  (criterion: == 0)\n", all_fails);
    printf("per-bit avg changed levels : %.4f (expect ~0.16 -> 1/6 level per bit)\n",
           (double)total_changes / flips);
    printf("per-bit level ratio       : %.4f (expect ~0.16)\n",
           (double)total_changes / (flips * FSQ_DIM));
    return (all_fails == 0) ? 0 : 1;
}

